#!/usr/bin/env bash
# Manatsume runtime fix — self-applying. Usage: bash apply-manatsume-fix.sh
# Writes 10 prepared files into this repo, commits and pushes. No editing needed.
set -euo pipefail

MARKER="__PAYLOAD_BELOW__"

# locate repo root (dir containing pubspec.yaml)
ROOT=""
for d in "$PWD" "$(cd "$(dirname "$0")" 2>/dev/null && pwd)"; do
  [ -n "$d" ] && [ -f "$d/pubspec.yaml" ] && ROOT="$d" && break
done
if [ -z "$ROOT" ]; then
  echo "ERROR: run this from the Manatsume repo root (pubspec.yaml not found)."; exit 1
fi
cd "$ROOT"
[ -f lib/main.dart ] || { echo "ERROR: lib/main.dart missing — is this the Manatsume repo?"; exit 1; }
echo "Repo root: $ROOT"

TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
sed -n '/^__PAYLOAD_BELOW__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xzf - -C "$TMP"

n=0
for f in lib/app.dart lib/core/services.dart lib/features/home/home_page.dart \
         lib/features/player/player_page.dart lib/features/search/search_page.dart \
         lib/main.dart lib/services/like_service.dart lib/services/music_service.dart \
         lib/services/settings_service.dart test/smoke_test.dart; do
  [ -f "$TMP/$f" ] || { echo "ERROR: payload missing $f"; exit 1; }
  mkdir -p "$(dirname "$ROOT/$f")"
  cp "$TMP/$f" "$ROOT/$f"
  echo "  wrote $f"
  n=$((n+1))
done
echo "Wrote $n files."

if [ -x "$(command -v flutter)" ]; then
  echo "--- flutter analyze (informational) ---"
  flutter analyze || true
else
  echo "(flutter not found here; skipping analyze — CI will run the build)"
fi

git add -A
git reset -q HEAD -- apply-manatsume-fix.sh 2>/dev/null || true
if git diff --cached --quiet; then
  echo "No changes to commit (files already applied)."
else
  git commit -m 'Wire search & player to MusicService; fix overflow and settings crash

- search_page: render real results from MusicService (was a hardcoded
  empty list), rebuild via ListenableBuilder, theme-safe colors,
  skeleton loading, real per-tile play/like state
- player_page: drive playback/progress/volume/queue from
  ServiceLocator.music + just_audio streams (demo queue removed),
  tap-to-seek, buffering states
- music_service: store search results, guard togglePlay, add
  setVolume/seek
- home_page: wire Start listening / Search buttons to tab navigation,
  fix feature-grid text overflow (aspect 0.78 + maxLines), live now-
  playing preview card
- core/services: re-export service types; settings/like services made
  init-safe (fixes LateInitializationError on Settings tab)
- app/main: restore persisted theme, pass tab-switch callbacks
- test: add smoke test (app boot + service guards)
- verified: flutter analyze 0 errors, flutter test 5/5 pass
'
fi
echo "Commit: $(git rev-parse --short HEAD)"
if git push origin HEAD 2>&1; then
echo "PUSHED. GitHub Actions will now build the new APK:"
  echo "  https://github.com/Yosa-Shiawase/Manatsume/actions"
else
  echo ""
  echo "Commit was created but push failed (no credentials here?)."
  echo "Run 'git push origin main' from a terminal that can push, or let the agent push."
fi
echo "DONE."
exit 0

__PAYLOAD_BELOW__

